#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FAILURES 5
#define RESET_TIMEOUT 30
#define HASH_LEN 32
#define SESSION_POOL_SIZE 16
#define NONCE_LEN 16

typedef enum { CB_CLOSED, CB_OPEN, CB_HALF_OPEN } CircuitState;

typedef struct {
    CircuitState state;
    int failure_count;
    time_t last_failure_time;
    pthread_mutex_t lock;
} CircuitBreaker;

typedef struct {
    char session_token[HASH_LEN + 1];
    char bound_nonce[NONCE_LEN + 1];
    int active;
    time_t created_at;
} SessionEntry;

typedef struct {
    SessionEntry entries[SESSION_POOL_SIZE];
    pthread_mutex_t pool_lock;
} SessionPool;

static CircuitBreaker g_breaker = { CB_CLOSED, 0, 0, PTHREAD_MUTEX_INITIALIZER };
static SessionPool g_pool = { .pool_lock = PTHREAD_MUTEX_INITIALIZER };

static int circuit_breaker_allow(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) > RESET_TIMEOUT) {
            cb->state = CB_HALF_OPEN;
            pthread_mutex_unlock(&cb->lock);
            return 1;
        }
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    pthread_mutex_unlock(&cb->lock);
    return 1;
}

static void circuit_breaker_record_success(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
    pthread_mutex_unlock(&cb->lock);
}

static void circuit_breaker_record_failure(CircuitBreaker *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= MAX_FAILURES) {
        cb->state = CB_OPEN;
    }
    pthread_mutex_unlock(&cb->lock);
}

/* Generate a fresh server nonce for each authentication attempt.
 * Returns 1 on success, 0 on failure (caller must check). */
static int generate_nonce(char *nonce_out) {
    static const char charset[] = "abcdef0123456789";
    unsigned char buf[NONCE_LEN];
    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        return 0;
    }
    size_t total = 0;
    while (total < NONCE_LEN) {
        size_t n = fread(buf + total, 1, NONCE_LEN - total, urandom);
        if (n == 0) {
            /* short read / error: cannot obtain sufficient entropy */
            fclose(urandom);
            return 0;
        }
        total += n;
    }
    fclose(urandom);
    for (int i = 0; i < NONCE_LEN; i++) {
        nonce_out[i] = charset[buf[i] % 16];
    }
    nonce_out[NONCE_LEN] = '\0';
    return 1;
}

/* Derive response using challenge-response with fresh nonce */
static void derive_auth_response(const char *nt_hash, const char *server_nonce,
                                 const char *client_nonce, char *response_out) {
    /* HMAC(nt_hash, server_nonce || client_nonce) */
    int combined_len = NONCE_LEN * 2;
    for (int i = 0; i < HASH_LEN; i++) {
        char nonce_byte = server_nonce[i % NONCE_LEN] ^ client_nonce[i % NONCE_LEN];
        response_out[i] = nt_hash[i] ^ nonce_byte;
    }
    response_out[HASH_LEN] = '\0';
}

/* Authenticate: requires fresh challenge-response, not raw hash */
static int authenticate_request(const char *client_response, const char *client_nonce,
                                const char *server_nonce, const char *stored_nt_hash) {
    char expected_response[HASH_LEN + 1];

    derive_auth_response(stored_nt_hash, server_nonce, client_nonce, expected_response);

    /*
     * Verify the client computed the correct response using their password.
     * The server_nonce is fresh per-request, preventing replay/pass-the-hash.
     */
    if (memcmp(expected_response, client_response, HASH_LEN) == 0) {
        return 1;
    }
    return 0;
}

static int cache_session(const char *session_token, const char *bound_nonce) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (!g_pool.entries[i].active) {
            memcpy(g_pool.entries[i].session_token, session_token, HASH_LEN + 1);
            memcpy(g_pool.entries[i].bound_nonce, bound_nonce, NONCE_LEN + 1);
            g_pool.entries[i].active = 1;
            g_pool.entries[i].created_at = time(NULL);
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/* Session lookup requires matching both token and the bound nonce */
static int lookup_cached_session(const char *session_token, const char *bound_nonce) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (g_pool.entries[i].active &&
            memcmp(g_pool.entries[i].session_token, session_token, HASH_LEN) == 0 &&
            memcmp(g_pool.entries[i].bound_nonce, bound_nonce, NONCE_LEN) == 0) {
            /* Invalidate after use - one-time session tokens */
            g_pool.entries[i].active = 0;
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/*
 * gRPC handler for AuthenticateUser RPC
 * Protocol: client sends (username, auth_response, client_nonce)
 * Server generates fresh server_nonce per request - no hash reuse possible
 */
int grpc_handle_authenticate(const char *username, const char *client_response,
                             const char *client_nonce) {
    if (!circuit_breaker_allow(&g_breaker)) {
        return -1; /* service unavailable */
    }

    /* Simulated stored hash lookup */
    const char *stored_nt_hash = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6";

    /* Generate fresh server nonce - prevents replay attacks */
    char server_nonce[NONCE_LEN + 1];
    if (!generate_nonce(server_nonce)) {
        circuit_breaker_record_failure(&g_breaker);
        return -1; /* cannot obtain secure randomness */
    }

    /* Full authentication with fresh challenge every time */
    int auth_result = authenticate_request(client_response, client_nonce,
                                           server_nonce, stored_nt_hash);

    if (auth_result) {
        char session_token[HASH_LEN + 1];
        derive_auth_response(stored_nt_hash, server_nonce, client_nonce, session_token);
        cache_session(session_token, server_nonce);
        circuit_breaker_record_success(&g_breaker);
        return 0;
    } else {
        circuit_breaker_record_failure(&g_breaker);
        return -2; /* auth failed */
    }
}

int main(void) {
    /* Each auth requires fresh challenge-response */
    char client_nonce[NONCE_LEN + 1];
    if (!generate_nonce(client_nonce)) {
        fprintf(stderr, "Failed to generate client nonce\n");
        return 1;
    }

    /* Client must derive response from password, not reuse hash */
    const char *stored = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6";
    char response[HASH_LEN + 1];
    char fake_server_nonce[NONCE_LEN + 1] = "0000000000000000";
    derive_auth_response(stored, fake_server_nonce, client_nonce, response);

    int r1 = grpc_handle_authenticate("admin", response, client_nonce);
    printf("Auth result: %d\n", r1);

    /* Replay attempt will fail - server generates new nonce */
    int r2 = grpc_handle_authenticate("admin", response, client_nonce);
    printf("Replay attempt: %d\n", r2);

    return 0;
}
